//! Golden tests for the seed port.
//!
//! `balatro-seed` claims byte-accuracy with the real game, and until this
//! file existed nothing in the workspace tested it. Every test in the crate
//! was either self-consistency or a range check — all of which would still
//! pass if every value were wrong by the same amount, including a mistranscribed
//! pool table.
//!
//! The fixtures in `tests/golden/` are the rendered output for four seeds.
//! They were generated by the code, so on their own they only pin
//! *stability*: they catch a refactor that changes the output, and they make
//! a drift visible in review rather than in a player's run. They do not prove
//! the values match the real game — that check is a human diffing against
//! <https://balatro.com/the-soul/>, and the numbers in the fixture headers
//! below are the ones that were diffed.
//!
//! `.gitignore` excludes `*.json`, so the fixtures are `.txt`.

use balatro_seed::render::{RenderOptions, render};
use std::path::Path;

fn opts() -> RenderOptions {
    RenderOptions {
        max_ante: 3,
        ..RenderOptions::default()
    }
}

/// The seeds with a golden fixture.
///
/// Only `TEST` has been diffed line-by-line against the real game by a
/// human — the README documents exactly that one. The others exist to make
/// the port fail loudly if two seeds start colliding or the rendering
/// regresses, and they have **not** been verified against the reference.
/// Adding a seed here does not make it verified; `VERIFIED` below is the
/// list that does.
const SEEDS: &[&str] = &["TEST", "AAA111", "ZZ9", "THE-SOUL"];

/// Seeds whose output a human has compared against the real game, with the
/// ante-1 boss, voucher and first shop item as read off the reference.
///
/// To add one: run `explore SEED --ante 1`, paste the reference site's
/// Output box for the same seed and settings (Red Deck, White Stake,
/// 1.0.1f, all unlocks on) into a diff, and only then add the row.
const VERIFIED: &[(&str, &str, &str, &str)] = &[("TEST", "The Goad", "Tarot Merchant", "Ice Cream")];

#[test]
fn rendered_seeds_match_their_fixtures() {
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/golden");
    let mut checked = 0;
    for seed in SEEDS {
        let path = dir.join(format!("{seed}.txt"));
        let expected = std::fs::read_to_string(&path)
            .unwrap_or_else(|e| panic!("could not read fixture {}: {e}", path.display()));
        let got = render(seed, &opts());
        assert_eq!(
            got,
            expected,
            "rendered output for {seed} changed.\nIf this is intended, regenerate the \
             fixtures: for s in {seeds}; do cargo run -q -p balatro-seed --bin explore \
             -- $s --ante 3 > balatro-seed/tests/golden/$s.txt; done",
            seeds = SEEDS.join(" ")
        );
        checked += 1;
    }
    assert_eq!(checked, SEEDS.len(), "every seed was checked");
}

/// The spot values that were diffed by hand against the real game. Separate
/// from the fixture comparison so a fixture regeneration cannot quietly
/// change them.
#[test]
fn known_values_still_match_the_real_game() {
    for (seed, boss, voucher, first_item) in VERIFIED {
        let out = render(seed, &opts());
        assert!(
            out.contains(&format!("Boss: {boss}\n")),
            "{seed}: boss is no longer {boss}"
        );
        assert!(
            out.contains(&format!("Voucher: {voucher}\n")),
            "{seed}: voucher is no longer {voucher}"
        );
        assert!(
            out.contains(&format!("1) {first_item}\n")),
            "{seed}: first shop item is no longer {first_item}"
        );
    }
}

/// Rendering must be deterministic: the same seed and options always give
/// byte-identical output, whatever order the calls happen in.
#[test]
fn rendering_is_deterministic() {
    for seed in SEEDS {
        let first = render(seed, &opts());
        for _ in 0..3 {
            assert_eq!(render(seed, &opts()), first, "{seed} is not stable");
        }
    }
}

/// Distinct seeds must produce distinct content, or the port is collapsing
/// seeds and the fixtures would all match each other.
#[test]
fn distinct_seeds_produce_distinct_output() {
    let outputs: Vec<String> = SEEDS.iter().map(|s| render(s, &opts())).collect();
    for (i, a) in outputs.iter().enumerate() {
        for (j, b) in outputs.iter().enumerate() {
            if i < j {
                assert_ne!(a, b, "seeds {} and {} are identical", SEEDS[i], SEEDS[j]);
            }
        }
    }
}

/// The seed normalisation the website applies: uppercased, and `0` folded to
/// `O` so the seed fits the fixed-width field the real game uses.
#[test]
fn seed_normalisation_matches_the_website() {
    let upper = render("test", &opts());
    assert_eq!(upper, render("TEST", &opts()), "seeds are uppercased");
    let folded = render("T0ST", &opts());
    assert_eq!(folded, render("TOST", &opts()), "0 folds to O");
}

/// Every option must actually change the output, or a flag is being ignored.
#[test]
fn render_options_change_the_output() {
    let base = render("TEST", &opts());

    let mut fewer_antes = opts();
    fewer_antes.max_ante = 1;
    assert_ne!(render("TEST", &fewer_antes), base, "--ante changes the output");

    let mut more_cards = opts();
    more_cards.cards_per_ante = vec![50, 50, 50];
    assert!(
        render("TEST", &more_cards).len() > base.len(),
        "--cards-per-ante changes the output"
    );

    let mut offered = opts();
    offered.vouchers_bought = false;
    assert_ne!(
        render("TEST", &offered),
        base,
        "--vouchers offered changes the output"
    );

    let mut inactive = opts();
    inactive.activate_vouchers = false;
    assert_ne!(
        render("TEST", &inactive),
        base,
        "--no-activate-vouchers changes the output"
    );

    let mut ante_0 = opts();
    ante_0.ante_0 = true;
    let with_ante_0 = render("TEST", &ante_0);
    assert!(
        with_ante_0.starts_with("==ANTE 0=="),
        "--ante-0 puts the preview first"
    );
    assert!(with_ante_0.len() > base.len(), "--ante-0 adds a section");
}
